	}

	var page *CallLogsPagination
	if payload.AdditionalData != nil {
		page = payload.AdditionalData.Pagination
	}
	return payload.Data, page, nil
}

func (p callLogPayload) toMap() map[string]interface{} {
	body := map[string]interface{}{}
	if p.userID != nil {
