41	type FilesOption interface {
42		applyFiles(*filesOptions)
43	}
44	
45	type filesOptions struct {
46		query          url.Values
47		fields         url.Values
48		requestOptions []pipedrive.RequestOption
49	}
50	
51	type filesOptionFunc func(*filesOptions)
52	
53	func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
54		f(cfg)
55	}
56	
